"""Utilities for migrating CFG-02 legacy storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import re


_LEGACY_DATE = re.compile(r"^\d{8}$")
_ISO_DATE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving nulls."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None
    if not isinstance(yyyymmdd, str) or not _LEGACY_DATE.fullmatch(yyyymmdd):
        raise ValueError("legacy date must be YYYYMMDD")

    try:
        parsed = date(
            int(yyyymmdd[0:4]),
            int(yyyymmdd[4:6]),
            int(yyyymmdd[6:8]),
        )
    except ValueError as exc:
        raise ValueError("legacy date is not a valid calendar date") from exc

    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD, preserving nulls."""
    if iso is None or iso == "":
        return "00000000"
    if not isinstance(iso, str) or not _ISO_DATE.fullmatch(iso):
        raise ValueError("ISO date must be YYYY-MM-DD")

    try:
        parsed = date.fromisoformat(iso)
    except ValueError as exc:
        raise ValueError("ISO date is not a valid calendar date") from exc

    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag, where blank means N, to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units using half-up rounding."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency.strip()
    exponent = 0 if currency_code == "JPY" else 2

    decimal_amount = Decimal(str(amount))
    scaled_amount = decimal_amount * (Decimal(10) ** exponent)
    return int(scaled_amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
